// Synced with n8n/code-nodes/normalize-lead.js (deterministic normalization for WF01)
function generateRandomHex8() {
  if (
    typeof globalThis.crypto !== 'undefined' &&
    typeof globalThis.crypto.getRandomValues === 'function'
  ) {
    const bytes = new Uint8Array(4);
    globalThis.crypto.getRandomValues(bytes);
    return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
  }
  return Math.floor(Math.random() * 0x100000000)
    .toString(16)
    .padStart(8, '0');
}

function generateSubmissionId(nowMs) {
  const ts = nowMs.toString(36);
  const rand = generateRandomHex8();
  return `sub_${ts}_${rand}`;
}

function normalizeInlineText(value) {
  if (typeof value !== 'string') return null;
  const collapsed = value.trim().replace(/\s+/g, ' ');
  return collapsed.length > 0 ? collapsed : null;
}

function normalizeMultilineText(value) {
  if (typeof value !== 'string') return '';
  return value
    .replace(/\r\n?/g, '\n')
    .split('\n')
    .map((line) => line.replace(/[ \t]+$/g, ''))
    .join('\n')
    .trim();
}

function normalizeBudgetAmount(value) {
  if (typeof value !== 'number' || !Number.isFinite(value)) return null;
  return Math.round(value * 100) / 100;
}

function normalizeTimelineWeeks(value) {
  if (typeof value !== 'number' || !Number.isFinite(value)) return null;
  const rounded = Math.trunc(value);
  return rounded > 0 ? rounded : null;
}

function normalizeBudgetCurrency(value) {
  if (typeof value !== 'string') return 'USD';
  const normalized = value.trim().toUpperCase();
  return /^[A-Z]{3}$/.test(normalized) ? normalized : 'USD';
}

const now = DateTime.now().toUTC();
const nowIso = now.toISO();
const nowMs = now.toMillis();
const webhookItems = $('Receive Lead Intake Webhook').all();

return webhookItems.map((item) => {
  const rawBody = item.json?.body;
  const body =
    rawBody && typeof rawBody === 'object' && !Array.isArray(rawBody)
      ? rawBody
      : {};

  const existingSubmissionId = normalizeInlineText(body.submission_id);
  const submissionIdGenerated = existingSubmissionId === null;
  const submissionId = existingSubmissionId ?? generateSubmissionId(nowMs);

  const consentToEmail = body.consent_to_email === true;
  const rawConsentTs = normalizeInlineText(body.consent_timestamp);

  return {
    json: {
      submission_id: submissionId,
      submission_id_generated: submissionIdGenerated,
      full_name: normalizeInlineText(body.full_name) ?? '',
      email:
        typeof body.email === 'string' ? body.email.trim().toLowerCase() : '',
      company_name: normalizeInlineText(body.company_name),
      phone: normalizeInlineText(body.phone),
      service_type: normalizeInlineText(body.service_type),
      budget_min: normalizeBudgetAmount(body.budget_min),
      budget_max: normalizeBudgetAmount(body.budget_max),
      budget_currency: normalizeBudgetCurrency(body.budget_currency),
      timeline_weeks: normalizeTimelineWeeks(body.timeline_weeks),
      project_description: normalizeMultilineText(body.project_description),
      consent_to_email: consentToEmail,
      consent_timestamp: consentToEmail ? (rawConsentTs ?? nowIso) : null,
      consent_source:
        normalizeInlineText(body.consent_source) ?? 'website_contact_form',
      lead_status: 'new',
      priority: 'low',
      approval_status: 'not_required',
      followup_status: 'not_eligible',
      received_at: nowIso,
    },
  };
});

