// Synced with n8n/code-nodes/validate-ai-output.js (WF01 strict AI JSON schema gate)
const PROMPT_VERSION = 'v1.0.0';
const MODEL_NAME = 'deepseek-chat';

const ALLOWED_SERVICES = [
  'Custom Web Applications & SaaS MVPs',
  'B2B Marketing & Corporate Websites',
  'Web App Redesign & Performance Optimization',
  'Third-party API & Database Integrations',
  'Out of Scope',
];

const ALLOWED_BANDS = ['high', 'medium', 'low'];
const FORBIDDEN_KEYS = ['qualification_score', 'qualification_status', 'priority'];

function stripMarkdownCodeFence(text) {
  const trimmed = text.trim();
  const fenceMatch = trimmed.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
  return fenceMatch ? fenceMatch[1].trim() : trimmed;
}

function validateAiQualificationOutput(rawOutput) {
  let parsed = null;
  let rawPreview = '';

  if (typeof rawOutput === 'string') {
    rawPreview = rawOutput.slice(0, 300);
    const cleaned = stripMarkdownCodeFence(rawOutput);
    if (!cleaned) {
      return {
        valid: false,
        model_name: MODEL_NAME,
        prompt_version: PROMPT_VERSION,
        error_code: 'MALFORMED_AI_JSON',
        error_message: 'AI response text is empty',
        errors: ['AI response text is empty'],
        raw_preview: rawPreview,
      };
    }
    try {
      parsed = JSON.parse(cleaned);
    } catch (err) {
      return {
        valid: false,
        model_name: MODEL_NAME,
        prompt_version: PROMPT_VERSION,
        error_code: 'MALFORMED_AI_JSON',
        error_message: 'Failed to parse AI JSON response: ' + (err && err.message ? err.message : 'SyntaxError'),
        errors: ['Invalid JSON syntax from LLM'],
        raw_preview: rawPreview,
      };
    }
  } else if (rawOutput && typeof rawOutput === 'object' && !Array.isArray(rawOutput)) {
    parsed = rawOutput;
    rawPreview = JSON.stringify(rawOutput).slice(0, 300);
  } else {
    return {
      valid: false,
      model_name: MODEL_NAME,
      prompt_version: PROMPT_VERSION,
      error_code: 'MALFORMED_AI_JSON',
      error_message: 'AI response must be a JSON string or object',
      errors: ['AI response must be a JSON string or object'],
      raw_preview: String(rawOutput ?? '').slice(0, 300),
    };
  }

  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    return {
      valid: false,
      model_name: MODEL_NAME,
      prompt_version: PROMPT_VERSION,
      error_code: 'MALFORMED_AI_JSON',
      error_message: 'Parsed AI output must be a plain JSON object',
      errors: ['Parsed AI output must be a plain JSON object'],
      raw_preview: rawPreview,
    };
  }

  const errors = [];

  for (const forbidden of FORBIDDEN_KEYS) {
    if (Object.prototype.hasOwnProperty.call(parsed, forbidden)) {
      errors.push('Forbidden LLM scoring key present: ' + forbidden);
    }
  }

  const detectedService = typeof parsed.detected_service === 'string' ? parsed.detected_service.trim() : '';
  if (!ALLOWED_SERVICES.includes(detectedService)) {
    errors.push('detected_service must be one of the 5 allowed categories (got "' + String(parsed.detected_service ?? '') + '")');
  }

  const projectSummary = typeof parsed.project_summary === 'string' ? parsed.project_summary.trim() : '';
  if (projectSummary.length < 10 || projectSummary.length > 1200) {
    errors.push('project_summary must be a string between 10 and 1200 characters');
  }

  const missingInformation = [];
  if (!Array.isArray(parsed.missing_information)) {
    errors.push('missing_information must be an array of strings');
  } else if (parsed.missing_information.length > 15) {
    errors.push('missing_information must contain at most 15 items');
  } else {
    for (let i = 0; i < parsed.missing_information.length; i++) {
      const entry = parsed.missing_information[i];
      if (typeof entry !== 'string' || !entry.trim()) {
        errors.push('missing_information[' + i + '] must be a non-empty string');
      } else {
        missingInformation.push(entry.trim().slice(0, 200));
      }
    }
  }

  const scopeFit = typeof parsed.scope_fit === 'string' ? parsed.scope_fit.trim().toLowerCase() : '';
  if (!ALLOWED_BANDS.includes(scopeFit)) {
    errors.push('scope_fit must be high, medium, or low (got "' + String(parsed.scope_fit ?? '') + '")');
  }

  if (typeof parsed.spam_suspected !== 'boolean') {
    errors.push('spam_suspected must be a boolean');
  }

  const clarityScoreBand = typeof parsed.clarity_score_band === 'string' ? parsed.clarity_score_band.trim().toLowerCase() : '';
  if (!ALLOWED_BANDS.includes(clarityScoreBand)) {
    errors.push('clarity_score_band must be high, medium, or low (got "' + String(parsed.clarity_score_band ?? '') + '")');
  }

  const draftEmailSubject = typeof parsed.draft_email_subject === 'string' ? parsed.draft_email_subject.trim() : '';
  if (draftEmailSubject.length < 3 || draftEmailSubject.length > 200) {
    errors.push('draft_email_subject must be a string between 3 and 200 characters');
  }

  const draftEmailBody = typeof parsed.draft_email_body === 'string' ? parsed.draft_email_body.trim() : '';
  if (draftEmailBody.length < 20 || draftEmailBody.length > 5000) {
    errors.push('draft_email_body must be a string between 20 and 5000 characters');
  }

  if (errors.length > 0) {
    return {
      valid: false,
      model_name: MODEL_NAME,
      prompt_version: PROMPT_VERSION,
      error_code: 'AI_SCHEMA_VALIDATION_ERROR',
      error_message: errors.join('; '),
      errors,
      raw_preview: rawPreview,
    };
  }

  return {
    valid: true,
    model_name: MODEL_NAME,
    prompt_version: PROMPT_VERSION,
    analysis: {
      detected_service: detectedService,
      project_summary: projectSummary,
      missing_information: missingInformation,
      scope_fit: scopeFit,
      spam_suspected: parsed.spam_suspected,
      clarity_score_band: clarityScoreBand,
      draft_email_subject: draftEmailSubject,
      draft_email_body: draftEmailBody,
      draft_email_snapshot: 'Subject: ' + draftEmailSubject + '\n\n' + draftEmailBody,
    },
  };
}

const items = $input.all();
return items.map((item) => {
  const raw = item.json?.text ?? item.json?.output ?? item.json;
  return { json: validateAiQualificationOutput(raw) };
});

// Synced with n8n/code-nodes/score-lead.js (deterministic 0-100 scoring + deal-breaker engine)
const OUT_OF_SCOPE_SERVICE = 'Out of Scope';

function scoreServiceFit(detectedService, scopeFit) {
  if (detectedService === OUT_OF_SCOPE_SERVICE) {
    return { points: 0, max: 30, reason: 'Service classified as Out of Scope (deal-breaker)' };
  }
  if (scopeFit === 'high') return { points: 30, max: 30, reason: 'High scope fit for ' + detectedService };
  if (scopeFit === 'medium') return { points: 18, max: 30, reason: 'Medium scope fit for ' + detectedService };
  return { points: 5, max: 30, reason: 'Low scope fit for ' + (detectedService || 'unknown service') };
}

function scoreBudgetFit(budgetMin, budgetMax) {
  const hasMin = typeof budgetMin === 'number' && Number.isFinite(budgetMin);
  const hasMax = typeof budgetMax === 'number' && Number.isFinite(budgetMax);
  const effectiveBudget = hasMax ? budgetMax : hasMin ? budgetMin : null;

  if (effectiveBudget === null) {
    return { points: 10, max: 30, effective_budget: null, undisclosed: true, borderline: false, below_floor: false, reason: 'Budget undisclosed (requires manual review)' };
  }
  if (effectiveBudget < 1500) {
    return { points: 0, max: 30, effective_budget: effectiveBudget, undisclosed: false, borderline: false, below_floor: true, reason: 'Effective budget ($' + effectiveBudget + ') is below $1,500 minimum (deal-breaker)' };
  }
  if (effectiveBudget < 3000) {
    return { points: 10, max: 30, effective_budget: effectiveBudget, undisclosed: false, borderline: true, below_floor: false, reason: 'Effective budget ($' + effectiveBudget + ') is in borderline $1,500-$2,999 band (capped at needs_review)' };
  }
  if (effectiveBudget < 5000) {
    return { points: 20, max: 30, effective_budget: effectiveBudget, undisclosed: false, borderline: false, below_floor: false, reason: 'Effective budget ($' + effectiveBudget + ') meets $3,000-$4,999 floor' };
  }
  if (effectiveBudget <= 25000) {
    return { points: 30, max: 30, effective_budget: effectiveBudget, undisclosed: false, borderline: false, below_floor: false, reason: 'Effective budget ($' + effectiveBudget + ') is within preferred $5,000-$25,000 sweet spot' };
  }
  return { points: 26, max: 30, effective_budget: effectiveBudget, undisclosed: false, borderline: false, below_floor: false, reason: 'Effective budget ($' + effectiveBudget + ') exceeds $25,000 (verify delivery capacity)' };
}

function scoreTimelineFit(timelineWeeks) {
  if (typeof timelineWeeks !== 'number' || !Number.isFinite(timelineWeeks)) {
    return { points: 8, max: 20, timeline_weeks: null, reason: 'Timeline unspecified' };
  }
  if (timelineWeeks >= 4 && timelineWeeks <= 16) {
    return { points: 20, max: 20, timeline_weeks: timelineWeeks, reason: 'Realistic timeline (' + timelineWeeks + ' weeks, target 4-16 weeks)' };
  }
  if ((timelineWeeks >= 2 && timelineWeeks <= 3) || (timelineWeeks >= 17 && timelineWeeks <= 24)) {
    return { points: 12, max: 20, timeline_weeks: timelineWeeks, reason: 'Tight or extended timeline (' + timelineWeeks + ' weeks)' };
  }
  return { points: 5, max: 20, timeline_weeks: timelineWeeks, reason: 'Aggressive (<2w) or very long (>24w) timeline (' + timelineWeeks + ' weeks)' };
}

function scoreProjectClarity(clarityScoreBand) {
  if (clarityScoreBand === 'high') return { points: 20, max: 20, clarity_score_band: 'high', reason: 'High project clarity with concrete requirements' };
  if (clarityScoreBand === 'medium') return { points: 12, max: 20, clarity_score_band: 'medium', reason: 'Moderate project clarity with some scope gaps' };
  return { points: 5, max: 20, clarity_score_band: 'low', reason: 'Low project clarity or insufficient detail' };
}

function scoreLead(lead, analysis) {
  const detectedService = typeof analysis.detected_service === 'string' ? analysis.detected_service.trim() : '';
  const scopeFit = typeof analysis.scope_fit === 'string' ? analysis.scope_fit.trim().toLowerCase() : 'low';
  const clarityBand = typeof analysis.clarity_score_band === 'string' ? analysis.clarity_score_band.trim().toLowerCase() : 'low';
  const spamSuspected = analysis.spam_suspected === true;
  const missingInfo = Array.isArray(analysis.missing_information) ? analysis.missing_information : [];

  const service = scoreServiceFit(detectedService, scopeFit);
  const budget = scoreBudgetFit(lead.budget_min, lead.budget_max);
  const timeline = scoreTimelineFit(lead.timeline_weeks);
  const clarity = scoreProjectClarity(clarityBand);
  const rawScore = Math.max(0, Math.min(100, service.points + budget.points + timeline.points + clarity.points));

  const dealBreakers = [];
  if (spamSuspected) dealBreakers.push('spam_suspected');
  if (detectedService === OUT_OF_SCOPE_SERVICE) dealBreakers.push('out_of_scope_service');
  if (budget.below_floor) dealBreakers.push('budget_below_1500');

  const overrides = [];
  let qualificationStatus;
  let priority;
  let approvalStatus;
  const followupStatus = 'not_eligible';

  if (dealBreakers.length > 0) {
    qualificationStatus = 'not_qualified';
    priority = 'low';
    approvalStatus = 'not_required';
    overrides.push('deal_breaker_override:' + dealBreakers.join(','));
  } else {
    if (rawScore >= 75) {
      qualificationStatus = 'qualified';
      priority = 'high';
      approvalStatus = 'pending';
    } else if (rawScore >= 45) {
      qualificationStatus = 'needs_review';
      priority = 'medium';
      approvalStatus = 'pending';
    } else {
      qualificationStatus = 'not_qualified';
      priority = 'low';
      approvalStatus = 'not_required';
    }

    if (budget.undisclosed || missingInfo.length >= 2) {
      if (qualificationStatus !== 'needs_review') {
        overrides.push(budget.undisclosed ? 'undisclosed_budget_requires_review' : 'missing_info_floor_requires_review');
      }
      qualificationStatus = 'needs_review';
      priority = 'medium';
      approvalStatus = 'pending';
    } else if (budget.borderline && qualificationStatus === 'qualified') {
      overrides.push('borderline_budget_capped_at_needs_review');
      qualificationStatus = 'needs_review';
      priority = 'medium';
      approvalStatus = 'pending';
    }
  }

  const finalScore = dealBreakers.length > 0 ? Math.min(rawScore, 44) : rawScore;
  return {
    qualification_score: finalScore,
    qualification_status: qualificationStatus,
    lead_status: qualificationStatus,
    priority,
    approval_status: approvalStatus,
    followup_status: followupStatus,
    needs_email_draft: qualificationStatus === 'qualified' || qualificationStatus === 'needs_review',
    score_breakdown: {
      service_fit: { points: service.points, max: service.max, reason: service.reason },
      budget_fit: { points: budget.points, max: budget.max, effective_budget: budget.effective_budget, reason: budget.reason },
      timeline_fit: { points: timeline.points, max: timeline.max, timeline_weeks: timeline.timeline_weeks, reason: timeline.reason },
      project_clarity: { points: clarity.points, max: clarity.max, clarity_score_band: clarity.clarity_score_band, reason: clarity.reason },
      raw_score: rawScore,
      final_score: finalScore,
      deal_breakers: dealBreakers,
      overrides,
      missing_information_count: missingInfo.length,
    },
  };
}

const normalizedLeads = $('Normalize Lead Data').all();
const validatedItems = $('Validate AI Output Schema').all();

return validatedItems.map((item, idx) => {
  const lead = normalizedLeads[idx]?.json ?? normalizedLeads[0]?.json ?? {};
  const analysis = item.json?.analysis ?? {};
  return { json: scoreLead(lead, analysis) };
});

additionalFields.firstName:
={{ (() => {
  // Split normalized full_name into firstName (first token)
  const parts = ($('Normalize Lead Data').item.json.full_name || '').trim().split(/\s+/);
  return parts[0] || '';
})() }}

additionalFields.lastName:
={{ (() => {
  // Remaining tokens after firstName become lastName
  const parts = ($('Normalize Lead Data').item.json.full_name || '').trim().split(/\s+/);
  return parts.length > 1 ? parts.slice(1).join(' ') : '';
})() }}

additionalFields.leadStatus:
={{ (() => {
  // Map deterministic qualification_status to HubSpot hs_lead_status enum
  const status = $('Score Lead Deterministically').item.json.qualification_status;
  if (status === 'qualified') return 'OPEN';
  if (status === 'needs_review') return 'IN_PROGRESS';
  return 'UNQUALIFIED';
})() }}

additionalFields.lifeCycleStage:
={{ (() => {
  // Map deterministic qualification_status to HubSpot lifecyclestage enum
  const status = $('Score Lead Deterministically').item.json.qualification_status;
  if (status === 'qualified') return 'salesqualifiedlead';
  if (status === 'needs_review') return 'lead';
  return 'other';
})() }}

additionalFields.message:
={{ (() => {
  // Structured LeadFlow AI snapshot stored in standard HubSpot message property
  const lead = $('Normalize Lead Data').item.json;
  const ai = $('Validate AI Output Schema').item.json.analysis;
  const score = $('Score Lead Deterministically').item.json;
  const inquiryId = $('Insert Inquiry').item.json.id;
  const budgetStr =
    lead.budget_min !== null && lead.budget_max !== null
      ? `${lead.budget_currency} ${lead.budget_min}-${lead.budget_max}`
      : lead.budget_max !== null
        ? `${lead.budget_currency} up to ${lead.budget_max}`
        : lead.budget_min !== null
          ? `${lead.budget_currency} ${lead.budget_min}+`
          : 'Undisclosed';
  const timelineStr = lead.timeline_weeks ? `${lead.timeline_weeks} weeks` : 'Unspecified';
  return [
    `[LeadFlow AI | ${String(score.qualification_status || '').toUpperCase()} | Score: ${score.qualification_score}/100 | Priority: ${score.priority}]`,
    `Service: ${ai.detected_service}`,
    `Budget: ${budgetStr} | Timeline: ${timelineStr}`,
    `Summary: ${ai.project_summary}`,
    `Inquiry ID: ${inquiryId} | Submission ID: ${lead.submission_id}`
  ].join('\n');
})() }}

fieldValues.fieldValue:
={{ (() => {
  // Store HubSpot contact ID as trimmed string (or null if absent to preserve UNIQUE constraint)
  const rawId = $('Upsert HubSpot Contact').item.json.vid ?? $('Upsert HubSpot Contact').item.json.id;
  return rawId !== undefined && rawId !== null && String(rawId).trim() !== '' ? String(rawId).trim() : null;
})() }}

={{ (() => {
  const status = $('Score Lead Deterministically').item.json.qualification_status;
  const rawId = $('Upsert HubSpot Contact').item.json.vid ?? $('Upsert HubSpot Contact').item.json.id;
  return {
    contact_id: $('Resolve Contact ID').item.json.contact_id,
    hubspot_contact_id: rawId !== undefined && rawId !== null ? String(rawId) : null,
    is_new: Boolean($('Upsert HubSpot Contact').item.json.isNew),
    hubspot_lead_status: status === 'qualified' ? 'OPEN' : status === 'needs_review' ? 'IN_PROGRESS' : 'UNQUALIFIED',
    hubspot_lifecycle_stage: status === 'qualified' ? 'salesqualifiedlead' : status === 'needs_review' ? 'lead' : 'other'
  };
})() }}

={{ (() => {
  // Support both string errors (HubSpot continueErrorOutput) and Error objects
  const err = $json.error;
  const msg = typeof err === 'string'
    ? err
    : (err?.message ?? $json.message ?? 'HubSpot contact sync failed');
  return String(msg).slice(0, 1000);
})() }}
